func testPortadorToOneConvenioBancarioUsingCVB(t *testing.T) {
	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var local Portador
	var foreign ConvenioBancario

	seed := randomize.NewSeed()
	if err := randomize.Struct(seed, &local, portadorDBTypes, true, portadorColumnsWithDefault...); err != nil {
		t.Errorf("Unable to randomize Portador struct: %s", err)
	}
	if err := randomize.Struct(seed, &foreign, convenioBancarioDBTypes, false, convenioBancarioColumnsWithDefault...); err != nil {
		t.Errorf("Unable to randomize ConvenioBancario struct: %s", err)
	}

	if err := foreign.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	queries.Assign(&local.CVBID, foreign.CVBID)
	if err := local.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	check, err := local.CVB().One(ctx, tx)
	if err != nil {
		t.Fatal(err)
	}

	if !queries.Equal(check.CVBID, foreign.CVBID) {
		t.Errorf("want: %v, got %v", foreign.CVBID, check.CVBID)
	}

	ranAfterSelectHook := false
	AddConvenioBancarioHook(boil.AfterSelectHook, func(ctx context.Context, e boil.ContextExecutor, o *ConvenioBancario) error {
		ranAfterSelectHook = true
		return nil
	})

	slice := PortadorSlice{&local}
	if err = local.L.LoadCVB(ctx, tx, false, (*[]*Portador)(&slice), nil); err != nil {
		t.Fatal(err)
	}
	if local.R.CVB == nil {
		t.Error("struct should have been eager loaded")
	}

	local.R.CVB = nil
	if err = local.L.LoadCVB(ctx, tx, true, &local, nil); err != nil {
		t.Fatal(err)
	}
	if local.R.CVB == nil {
		t.Error("struct should have been eager loaded")
	}

	if !ranAfterSelectHook {
		t.Error("failed to run AfterSelect hook for relationship")
	}
}

