func testPortadorToOneSetOpConvenioBancarioUsingCVB(t *testing.T) {
	var err error

	ctx := context.Background()
	tx := MustTx(boil.BeginTx(ctx, nil))
	defer func() { _ = tx.Rollback() }()

	var a Portador
	var b, c ConvenioBancario

	seed := randomize.NewSeed()
	if err = randomize.Struct(seed, &a, portadorDBTypes, false, strmangle.SetComplement(portadorPrimaryKeyColumns, portadorColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	if err = randomize.Struct(seed, &b, convenioBancarioDBTypes, false, strmangle.SetComplement(convenioBancarioPrimaryKeyColumns, convenioBancarioColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}
	if err = randomize.Struct(seed, &c, convenioBancarioDBTypes, false, strmangle.SetComplement(convenioBancarioPrimaryKeyColumns, convenioBancarioColumnsWithoutDefault)...); err != nil {
		t.Fatal(err)
	}

	if err := a.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}
	if err = b.Insert(ctx, tx, boil.Infer()); err != nil {
		t.Fatal(err)
	}

	for i, x := range []*ConvenioBancario{&b, &c} {
		err = a.SetCVB(ctx, tx, i != 0, x)
		if err != nil {
			t.Fatal(err)
		}

		if a.R.CVB != x {
			t.Error("relationship struct not set to correct value")
		}

		if x.R.CVBPortadors[0] != &a {
			t.Error("failed to append to foreign relationship struct")
		}
		if !queries.Equal(a.CVBID, x.CVBID) {
			t.Error("foreign key was wrong value", a.CVBID)
		}

		zero := reflect.Zero(reflect.TypeOf(a.CVBID))
		reflect.Indirect(reflect.ValueOf(&a.CVBID)).Set(zero)

		if err = a.Reload(ctx, tx); err != nil {
			t.Fatal("failed to reload", err)
		}

		if !queries.Equal(a.CVBID, x.CVBID) {
			t.Error("foreign key was wrong value", a.CVBID, x.CVBID)
		}
	}
}

